/* Z-Pattern Layout 全局样式 */

/* Z型布局容器 */
.z-layout {
  max-width: 1200px;
  margin: 0 auto;
}

/* Z的第一行：品牌 + 导航/CTA */
.z-top-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1rem 1.5rem;
}

/* Z的对角线区域：核心内容 */
.z-diagonal {
  text-align: center;
  padding: 5rem 1.5rem;
  max-width: 800px;
  margin: 0 auto;
}

/* Z的第二行：信任 + 最终CTA */
.z-bottom-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 2rem 1.5rem;
}

/* Z路径上的关键点 */
.z-point {
  position: relative;
}

.z-point::after {
  content: '';
  position: absolute;
  width: 8px;
  height: 8px;
  background: #6366f1;
  border-radius: 50%;
}

/* 响应式 */
@media (max-width: 768px) {
  .z-top-bar,
  .z-bottom-bar {
    flex-direction: column;
    gap: 1rem;
    text-align: center;
  }
  .z-diagonal {
    padding: 3rem 1.5rem;
  }
}
/* Z-Pattern Layout Design Tokens */
:root {
  --z-pattern-layout-primary: #0f172a;
  --z-pattern-layout-secondary: #ffffff;
  --z-pattern-layout-accent: #6366f1;
  --z-pattern-layout-glow: rgba(15, 23, 42, 0.3);
}

@keyframes z-pattern-layout-fade-in {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes z-pattern-layout-pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.7; }
}

.z-pattern-layout-gradient {
  background: linear-gradient(135deg, #0f172a, #6366f1);
}

.z-pattern-layout-gradient-text {
  background: linear-gradient(135deg, #0f172a, #6366f1);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.z-pattern-layout-frosted {
  backdrop-filter: blur(12px) saturate(180%);
  -webkit-backdrop-filter: blur(12px) saturate(180%);
  background: rgba(15, 23, 42, 0.08);
}

.z-pattern-layout-accent-corner {
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 2rem), calc(100% - 2rem) 100%, 0 100%);
}

.z-pattern-layout-animate-in {
  animation: z-pattern-layout-fade-in 0.5s ease-out both;
}
